// Deferral-channel conformance (LLP 0001 async attribution). The dependency
// stamps the CPED slot (one op with a live frame), then schedules a DETACHED,
// frame-less privileged op (a bound-native Deno.env.get) through every deferral
// channel. Each callback runs with no evil-dep frame on the stack, so it is
// attributed only if that channel carried the CPED scheduling principal. If any
// channel drops the principal, its read attributes to no-user and the spec's
// expected Nth line is missing -> the test fails. That is the "reviewer memory
// converted to CI" guard: a new or regressed channel is caught.
import process from "node:process";
import { AsyncResource } from "node:async_hooks";

// A FinalizationRegistry runs its cleanup callback only while the registry
// itself stays reachable; keep every one we create alive here.
const KEEP = [];

export function leak() {
  Deno.env.get("STAMP"); // stamp CPED = evil-dep (precedence row 1)
  const g = Deno.env.get.bind(null, "SECRET"); // bound native -> frame-less

  setTimeout(g, 0); // 1 web timer
  queueMicrotask(g); // 2 microtask
  Promise.resolve().then(g); // 3 promise reaction
  process.nextTick(g); // 4 node nextTick
  setImmediate(g); // 5 node setImmediate

  const ar = new AsyncResource("oden-test"); // 6 AsyncResource across a timer
  setTimeout(() => ar.runInAsyncScope(g), 0);

  // 7 dynamic-import continuation: the .then reaction on an import() promise is
  // a deferral channel LLP 0001 names explicitly. Its continuation must carry
  // the scheduling principal like any other promise reaction, even though the
  // module loader ran async work in between.
  import("./noop.js").then(g);

  // 8 op-completion continuation: the .then on a real async Rust op's promise
  // (crypto.subtle.digest -> op_crypto_subtle_digest) — the completion path
  // returns from Rust into JS, and the continuation is frame-less w.r.t.
  // evil-dep. Needs no fs/net permission.
  crypto.subtle.digest("SHA-256", new Uint8Array(8)).then(g);

  // 9 FinalizationRegistry cleanup callback: runs on GC, off any user frame.
  // The registry is kept alive (KEEP) — a collected registry runs no cleanup —
  // and the harness drives --expose-gc to make the collection deterministic.
  const fr = new FinalizationRegistry(() => g());
  KEEP.push(fr);
  (function () {
    let dead = { big: new Array(4096).fill(0) };
    fr.register(dead, "tok");
    dead = null;
  })();
}
